def test_task_3_model_dispatched_mutations_prompt_exactly_once(tmp_path):
    path = tmp_path / "answer.py"
    path.write_text("ANSWER = 41\n", encoding="utf-8")
    confirmations = []
    workspace = Workspace(
        ToolPolicy(tmp_path, allow_writes=True),
        confirm_tool=lambda action: confirmations.append(action.tool) or True,
    )
    workspace.read_file("answer.py")

    edit_result = workspace.execute(
        ToolAction(
            "edit_file",
            {"path": "answer.py", "old": "41", "new": "42"},
        )
    )
    write_result = workspace.execute(
        ToolAction("write_file", {"path": "new.txt", "content": "data"})
    )

    assert edit_result == "wrote answer.py"
    assert write_result == "wrote new.txt"
    assert confirmations == ["edit_file", "write_file"]
    assert path.read_text(encoding="utf-8") == "ANSWER = 42\n"


