def test_task_2_tracks_a_file_when_commit_outcome_is_uncertain(tmp_path, monkeypatch):
    path = tmp_path / "answer.py"
    path.write_text("ANSWER = 41\n", encoding="utf-8")
    workspace = Workspace(
        ToolPolicy(tmp_path, allow_writes=True),
        confirm_tool=lambda action: True,
    )
    workspace.read_file("answer.py")

    def replace_then_interrupt(target, content):
        target.write_bytes(content)
        raise KeyboardInterrupt

    monkeypatch.setattr(workspace, "_atomic_write", replace_then_interrupt)

    with pytest.raises(KeyboardInterrupt):
        workspace.execute(
            ToolAction(
                "edit_file",
                {"path": "answer.py", "old": "41", "new": "42"},
            )
        )

    assert path.read_text(encoding="utf-8") == "ANSWER = 42\n"
    assert workspace.modified_files == set()
    assert workspace.uncertain_modified_files == {path}


