def test_cli_confirmation_escapes_terminal_control_characters(
    tmp_path, monkeypatch, capsys
):
    monkeypatch.setattr(sys, "stdin", _TtyInput())
    monkeypatch.setattr("builtins.input", lambda prompt: "n")
    action = ToolAction(
        "write_file",
        {"path": "\x1b[2J\u202eevil.txt", "content": "data"},
    )

    assert not confirm_tool_call(action, tmp_path)
    output = capsys.readouterr().out
    assert "\x1b" not in output
    assert "\u202e" not in output
    assert "\\u001b" in output
    assert "\\u202e" in output


class _EmptyStdout:
    def read(self, size):
        return b""

    def close(self):
        pass


class _PartiallyFailingStdout:
    def __init__(self):
        self.read_calls = 0

    def read(self, size):
        self.read_calls += 1
        if self.read_calls == 1:
            return b"x" * 128
        raise OSError("output pipe failed")

    def close(self):
        pass


class _FailingStdout:
    def read(self, size):
        raise OSError("output pipe failed")

    def close(self):
        pass


class _SynchronousThread:
    def __init__(self, *, target, daemon):
        self.target = target

    def start(self):
        self.target()

    def join(self, timeout=None):
        pass

    def is_alive(self):
        return False


class _InterruptedProcess:
    pid = 12345

    def __init__(self, error):
        self.stdout = _EmptyStdout()
        self.error = error
        self.wait_calls = 0
        self.killed = False

    def wait(self, timeout=None):
        self.wait_calls += 1
        if self.wait_calls == 1:
            raise self.error
        return -9

    def kill(self):
        self.killed = True


def test_task_3_keyboard_interrupt_kills_and_reaps_the_process_group(
    tmp_path, monkeypatch
):
    command = ["safe-tool"]
    process = _InterruptedProcess(KeyboardInterrupt())
    killed_groups = []
    popen_calls = []

    def start_process(*args, **kwargs):
        popen_calls.append((args, kwargs))
        return process

    patch_workspace_popen(monkeypatch, start_process)
    patch_workspace_killpg(
        monkeypatch, lambda pid, sig: killed_groups.append((pid, sig))
    )
    workspace = Workspace(ToolPolicy(tmp_path, allowed_commands=(tuple(command),)))

    with pytest.raises(KeyboardInterrupt):
        workspace.run_command(command)

    assert killed_groups == [(process.pid, 9)]
    assert process.wait_calls == 2
    assert workspace.command_side_effects_untracked
    assert len(popen_calls) == 1
    _, popen_kwargs = popen_calls[0]
    assert popen_kwargs["start_new_session"] is True
    assert popen_kwargs["shell"] is False
    assert popen_kwargs["stdin"] is subprocess.DEVNULL


