class _CompletedProcess:
    pid = 54321

    def __init__(self, returncode=0):
        self.stdout = _EmptyStdout()
        self.returncode = returncode
        self.wait_calls = 0

    def wait(self, timeout=None):
        self.wait_calls += 1
        return self.returncode

    def kill(self):
        pass


